solutions.javascript:
const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(BigInt);
function extGcd(a, b) {
  let x0 = 1n, y0 = 0n, x1 = 0n, y1 = 1n;
  while (b !== 0n) {
    const q = a / b;
    [a, b] = [b, a - q * b];
    [x0, x1] = [x1, x0 - q * x1];
    [y0, y1] = [y1, y0 - q * y1];
  }
  return [a, x0, y0];
}
const t = Number(tok[0]);
const out = [];
for (let i = 0; i < t; i++) {
  const a = tok[1 + 3 * i], b = tok[2 + 3 * i], m = tok[3 + 3 * i];
  const [g, x] = extGcd(a % m, m);               // BigInt: products reach 10^18, beyond exact Number range
  if (b % g !== 0n) { out.push('-1'); continue; }
  const mm = m / g;
  let r = (x * ((b / g) % mm)) % mm;
  if (r < 0n) r += mm;
  out.push(r.toString());
}
console.log(out.join('\n'));

