import java.io.*;
import java.util.*;

public class Main {
    static long x;                                   // coefficient found by extGcd
    static long extGcd(long a, long b) {             // returns g and leaves x with a*x + b*y = g
        long x0 = 1, x1 = 0;
        while (b != 0) {
            long q = a / b;
            long t = a - q * b; a = b; b = t;
            t = x0 - q * x1; x0 = x1; x1 = t;
        }
        x = x0;
        return a;
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StreamTokenizer st = new StreamTokenizer(br);
        st.nextToken();
        int t = (int) st.nval;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < t; i++) {
            st.nextToken(); long a = (long) st.nval;
            st.nextToken(); long b = (long) st.nval;
            st.nextToken(); long m = (long) st.nval;
            long g = extGcd(a % m, m);
            if (b % g != 0) { sb.append(-1).append('\n'); continue; }
            long mm = m / g;
            long r = (x % mm) * ((b / g) % mm) % mm;       // both factors are below 10^9, so the product fits in a long
            if (r < 0) r += mm;
            sb.append(r).append('\n');
        }
        System.out.print(sb);
    }
}

