#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
ll extGcd(ll a, ll b, ll &x, ll &y) {
    if (b == 0) { x = 1; y = 0; return a; }
    ll x1, y1;
    ll g = extGcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}
int main() {
    int t;
    scanf("%d", &t);
    while (t--) {
        ll a, b, m;
        scanf("%lld %lld %lld", &a, &b, &m);
        ll x, y;
        ll g = extGcd(a % m, m, x, y);
        if (b % g != 0) { printf("-1\n"); continue; }
        ll mm = m / g;
        ll r = (x % mm) * ((b / g) % mm) % mm;
        if (r < 0) r += mm;
        printf("%lld\n", r);
    }
    return 0;
}
